const endpoint = 'https://ai-gateway.vercel.sh/typesafe/v1/systemone';
const model = 'typesafe-ai/jev';

// Keep each expected result beside its synthetic email.
const cases = [{ id: 'C1', from: 'maya@northstar.example', subject: 'Launch approval needed', body: 'Can you approve the client launch plan before 3 PM?', expectedChoice: 'Clients', expectedReview: false }, { id: 'C2', from: 'devon@acme.example', subject: 'Project timeline question', body: 'Could we move the client review meeting to Thursday?', expectedChoice: 'Clients', expectedReview: false }, { id: 'R1', from: 'orders@shop.example', subject: 'Receipt for order 4821', body: 'Your payment of 48 dollars was received.', expectedChoice: 'Receipts', expectedReview: false }, { id: 'R2', from: 'billing@software.example', subject: 'Subscription renewal receipt', body: 'Your annual subscription renewed successfully.', expectedChoice: 'Receipts', expectedReview: false }, { id: 'N1', from: 'digest@techbrief.example', subject: 'Weekly product digest', body: 'Here are this week’s product launches and industry stories.', expectedChoice: 'Newsletters', expectedReview: false }, { id: 'N2', from: 'news@designnotes.example', subject: 'Design Notes issue 42', body: 'Read the latest design links and tutorials.', expectedChoice: 'Newsletters', expectedReview: false }, { id: 'P1', from: 'sam@example.com', subject: 'Dinner on Saturday', body: 'Are you free for dinner with the family this weekend?', expectedChoice: 'Personal', expectedReview: false }, { id: 'P2', from: 'lee@example.com', subject: 'Trip photos', body: 'I uploaded our holiday photos for you.', expectedChoice: 'Personal', expectedReview: false }, { id: 'A1', from: 'updates@example.com', subject: 'Please review', body: 'Can you look at this when you have time?', expectedChoice: null, expectedReview: true }, { id: 'A2', from: 'notice@example.com', subject: 'Your update is ready', body: 'The requested update is now available.', expectedChoice: null, expectedReview: true }];

return cases.map((test) => ({ json: { ...test, endpoint, model } }));

const tests = $('Generate Synthetic Emails').all();
const results = $input.all();
const threshold = 0.8;

// Pair each typed answer with the expected outcome.
const rows = results.map((result, index) => { const test = tests[index].json; const answer = result.json.answers?.category ?? {}; const values = Object.values(answer.probabilities ?? {}); const confidence = Number(answer.confidence ?? (values.length ? Math.max(...values) : 0)); let outcome = 'REVIEW'; if (test.expectedReview) outcome = confidence < threshold ? 'SAFE REVIEW' : 'UNSAFE ACCEPT'; else if (confidence >= threshold) outcome = answer.choice === test.expectedChoice ? 'PASS' : 'INCORRECT ACCEPT'; return { rowType: 'CASE', id: test.id, expected: test.expectedReview ? 'Review' : test.expectedChoice, choice: answer.choice ?? 'No answer', confidence: Number(confidence.toFixed(3)), outcome, inputTokens: Number(result.json.usage?.input_tokens ?? 0) }; });

// Add one summary row for a quick gate check.
const summary = { rowType: 'SUMMARY', totalCases: rows.length, threshold, clearPasses: rows.filter((row) => row.outcome === 'PASS').length, reviewCases: rows.filter((row) => row.outcome === 'REVIEW').length, safeAmbiguousReviews: rows.filter((row) => row.outcome === 'SAFE REVIEW').length, unsafeAmbiguousAccepts: rows.filter((row) => row.outcome === 'UNSAFE ACCEPT').length, incorrectAccepts: rows.filter((row) => row.outcome === 'INCORRECT ACCEPT').length, totalInputTokens: rows.reduce((sum, row) => sum + row.inputTokens, 0) };
return [...rows.map((row) => ({ json: row })), { json: summary }];
